import sys

def is_valid_word(s):
    if not s or len(s) > 16:
        return False
    for c in s:
        if not (c.isalnum() or c == '_'):
            return False
    return True

def main():
    s = sys.stdin.readline().rstrip('\n')

    if '/' in s:
        parts = s.split('/')
        if len(parts) != 2:
            print("NO")
            return
        user_host, resource = parts
        if not is_valid_word(resource):
            print("NO")
            return
    else:
        user_host = s
        resource = None

    if '@' not in user_host:
        print("NO")
        return

    at_index = user_host.index('@')
    username = user_host[:at_index]
    hostname = user_host[at_index+1:]

    if not is_valid_word(username):
        print("NO")
        return

    if not hostname or len(hostname) > 32:
        print("NO")
        return

    host_words = hostname.split('.')
    if not host_words:
        print("NO")
        return

    for word in host_words:
        if not is_valid_word(word):
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
    main()
